using System;using System.IO;using System.Reflection;using System.Runtime.Serialization;using System.Collections.Generic;using ElementalHearts;using RimWorld;using Verse;
class WaterLineageRegression {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
 static T Empty<T>(){return (T)FormatterServices.GetUninitializedObject(typeof(T));}static void Check(bool ok,string label){if(!ok)throw new Exception(label);}
 static int Main(string[] args){AppDomain.CurrentDomain.AssemblyResolve+=(s,e)=>{string n=new AssemblyName(e.Name).Name;string p=n=="ElementalHearts"?args[1]:n=="0Harmony"?args[2]:Path.Combine(args[0],n+".dll");return File.Exists(p)?Assembly.LoadFrom(p):null;};try{typeof(WaterLineageRegression).GetMethod("Run",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,null);return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
 static void Run(){
  var source=new HediffComp_WaterDefense{autoCombat=false,nonLethal=true,readyAt=999};var victim=Empty<Pawn>();typeof(HediffComp_WaterDefense).GetField("pending",F).SetValue(source,victim);typeof(HediffComp_WaterDefense).GetField("pendingAt",F).SetValue(source,800);typeof(HediffComp_WaterDefense).GetField("pendingUntil",F).SetValue(source,920);var dest=new HediffComp_WaterDefense();source.CopyStateTo(dest);Check(!dest.autoCombat&&dest.nonLethal&&dest.readyAt==999&&object.ReferenceEquals(typeof(HediffComp_WaterDefense).GetField("pending",F).GetValue(dest),victim)&&(int)typeof(HediffComp_WaterDefense).GetField("pendingAt",F).GetValue(dest)==800&&(int)typeof(HediffComp_WaterDefense).GetField("pendingUntil",F).GetValue(dest)==920,"promotion resets defense state");
  var disciple=new HediffComp_WaterAbilities{props=new HediffCompProperties_WaterAbilities{cooldownFactor=1.5f}};var ascendant=new HediffComp_WaterAbilities{props=new HediffCompProperties_WaterAbilities()};foreach(WaterPower power in Enum.GetValues(typeof(WaterPower)))Check(disciple.Cooldown(power)==(int)Math.Ceiling(ascendant.Cooldown(power)*1.5f),"disciple cooldown not 50% longer");
  var pawn=Empty<Pawn>();pawn.health=Empty<Pawn_HealthTracker>();pawn.health.hediffSet=Empty<HediffSet>();pawn.health.hediffSet.hediffs=new List<Hediff>();var h=new HediffWithComps{pawn=pawn,def=new HediffDef{defName="EH_WaterHeart",tags=new List<string>{ElementalHeartUtility.HeartTag}},comps=new List<HediffComp>()};pawn.health.hediffSet.hediffs.Add(h);Check(ElementalTeaching.Element(pawn)=="Water","Water lineage does not teach Water");h.def=new HediffDef{defName="EH_WaterTraining"};h.comps.Add(new HediffComp_ElementalApprentice{parent=h});Check(ElementalTeaching.Element(pawn)==null&&ElementalTeaching.Trained(pawn)&&ElementalTeaching.DamageFactor(pawn)==.4f,"Water pupil gains teaching or full damage");Check(DiscipleProgressRules.Eligible(50,300000)&&!DiscipleProgressRules.Eligible(49,300000)&&!DiscipleProgressRules.Eligible(50,299999),"promotion threshold changed");
  var frames=new HashSet<int>();for(int tick=0;tick<300;tick++){frames.Add(WaterAuraRules.Frame(tick,1));float alpha=WaterAuraRules.Opacity(tick,1);Check(alpha>=.1699f&&alpha<=.2701f,"aura not subtle or pulse unbounded");}Check(frames.Count==6,"aura misses frames");int shown=0;for(int bits=0;bits<64;bits++)if(WaterAuraRules.Visible((bits&1)!=0,(bits&2)!=0,(bits&4)!=0,(bits&8)!=0,(bits&16)!=0,(bits&32)!=0))shown++;Check(shown==1&&WaterAuraRules.Visible(true,true,true,false,true,true),"aura shows for disciple, undrafted, reverted or incapacitated pawn");
  Console.WriteLine("PASS: Water teacher/disciple identity, 40% damage, 50% longer active cooldowns, promotion boundaries and copied defense/pending-counter state.");Console.WriteLine("PASS: exactly six aura phases, 17-27% opacity pulse and transformed/drafted/alive/standing ascendant gates.");
 }
}
